import { Component } from '@angular/core';
import { GalleryCounter } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';

@Component({
  selector: 'app-demo',
  imports: [GalleryCounter, GalleryModule],
  template: `
    <gallery class="gallery-example" [items]="items">
        <div *galleryItemDef="let item; index as i" class="slide">
            <span>{{ i + 1 }}</span>
        </div>
        <gallery-counter [align]="align"/>
    </gallery>`,
})
export class DemoComponent {
  align = 'top';
}

documentations-counter--custom-counter.snippet:
import { Component } from '@angular/core';
import { GalleryCounter } from 'ng-gallery';
import { GalleryModule } from 'ng-gallery';

@Component({
  selector: 'app-demo',
  imports: [GalleryCounter, GalleryModule],
  template: `
    <gallery #gallery="gallery" class="gallery-example" [items]="items">
        <div *galleryItemDef="let item; index as i" class="slide">
            <span>{{ i + 1 }}</span>
        </div>
        <div
            class="g-panel custom-counter"
            gallerySlot
            gallerySlotAlign="start">
            Slide {{ gallery.activeIndex() + 1 }} of {{ gallery.itemsCount() }}
        </div>
    </gallery>`,
})
export class DemoComponent {}
